// Importing necessary Verus modules
use verus::*;

#[verus]
pub fn create_row(n: u8) -> Vec<u8> {
    // Precondition: n must be an 8-bit unsigned integer (0 <= n <= 255)
    assert(0 <= n && n <= 255);

    // Create a vector to hold the row
    let mut row: Vec<u8> = Vec::new();

    // Invariant: The length of the row should be equal to n
    // and the elements should be strictly increasing
    // This invariant will be maintained throughout the loop
    let mut i: u8 = 0;
    while i < n {
        // Push the current index i into the row
        row.push(i);
        // Increment i
        i = i + 1;
    }

    // Postcondition: The row should have length n and contain elements 0 to n-1
    assert(row.len() == n as usize);
    for j in 0..n {
        assert(row[j as usize] == j);
    }

    row
}

#[verus]
pub fn indices(n: u8) -> Vec<Vec<u8>> {
    // Precondition: n must be an 8-bit unsigned integer (0 <= n <= 255)
    assert(0 <= n && n <= 255);

    // Create a vector to hold the grid
    let mut grid: Vec<Vec<u8>> = Vec::new();

    // Create the row using the create_row function
    let row = create_row(n);

    // Add the row to the grid
    grid.push(row);

    // Postcondition: The grid should contain exactly one row of length n
    assert(grid.len() == 1);
    assert(grid[0].len() == n as usize);

    grid
}